 if(btn.hasAttribute('data-partner-location')){navigator.geolocation?.getCurrentPosition(async p=>{try{await operations('partner_location',{latitude:p.coords.latitude,longitude:p.coords.longitude});alert('Service location saved.')}catch(e){alert(e.message)}},()=>alert('Location could not be obtained. Allow location permission and retry.'),{timeout:12000,enableHighAccuracy:true});return;}
 if(btn.dataset.zoneCenter)return run(btn,async()=>{const lat=prompt('Actual zone centre latitude:'),lng=lat&&prompt('Actual zone centre longitude:');if(!lat||!lng)return;await operations('set_zone_center',{user_id:btn.dataset.zoneCenter,latitude:Number(lat),longitude:Number(lng)});await loadAdmin()});
 if(btn.dataset.settleDue)return run(btn,async()=>{const amount=prompt('Actual platform commission received, in ₹:'),reference=amount&&prompt('Received bank/UPI transfer reference:');if(!amount||!reference)return;await operations('settle_cash_due',{user_id:btn.dataset.settleDue,amount_paise:Math.round(Number(amount)*100),reference});await loadAdmin()});
