let signatureInk=false;function setupSignature(){signatureInk=false;const c=$('#signature-canvas'),ctx=c.getContext('2d');let drawing=false;ctx.lineWidth=2;ctx.lineCap='round';const point=e=>{const r=c.getBoundingClientRect();return [(e.clientX-r.left)*c.width/r.width,(e.clientY-r.top)*c.height/r.height]};c.addEventListener('pointerdown',e=>{drawing=true;c.setPointerCapture(e.pointerId);ctx.beginPath();ctx.moveTo(...point(e))});c.addEventListener('pointermove',e=>{if(!drawing)return;signatureInk=true;ctx.lineTo(...point(e));ctx.stroke()});c.addEventListener('pointerup',()=>drawing=false);$('#clear-signature').onclick=()=>{ctx.clearRect(0,0,c.width,c.height);signatureInk=false};}
document.addEventListener('change',async e=>{if(e.target.id==='reschedule-date'){try{const f=$('#reschedule-form'),rows=await client.rpc('carmitra_available_slots',{p_date:e.target.value,p_services:f.dataset.services.split(',').map(Number)});$('#reschedule-slots').innerHTML=rows.length?select('reschedule-slot','New slot',rows.map(s=>[s.id,date(s.starts_at)])):'<p>No available slots.</p>'}catch(e){$('#reschedule-slots').innerHTML=E(e.message)}}if(e.target.id==='redeem-date'){try{const rows=await client.rpc('carmitra_available_slots',{p_date:e.target.value,p_services:[1]});$('#redeem-slots').innerHTML=rows.length?select('redeem-slot','Available slot',rows.map(s=>[s.id,date(s.starts_at)])):'<p>No available slots for this date.</p>'}catch(err){$('#redeem-slots').innerHTML=E(err.message)}}});
document.addEventListener('submit',async e=>{const f=e.target;if(!['live-partner-form','channel-form','payout-form','admin-editor','cancel-form','review-form','warranty-form','signature-form','redeem-form','reschedule-form','profile-form','nominee-form'].includes(f.id)&&!f.classList.contains('job-form'))return;e.preventDefault();const btn=f.querySelector('button:not([type="button"])');await run(btn,async()=>{const data=Object.fromEntries(new FormData(f));if(f.id==='live-partner-form'){if(portalStep<3){Object.assign(application,data);if(portalStep===2){application.transportation=data.transportation==='on';application.skills=new FormData(f).getAll('skills').map(Number);if(!application.skills.length)throw Error('Select at least one service skill.');}portalStep++;render('partner',false);return;}if(!$('#partner-agreement-consent').checked)throw Error('Please read and accept the Partner Agreement.');if(!$('#verification-consent').checked)throw Error('Please consent to verification.');for(const key of ['identity','photo','police']){const file=$('#doc-'+key).files[0];if(file){if(key==='photo'&&!['image/jpeg','image/png','image/webp'].includes(file.type))throw Error('Upload a JPG, PNG or WebP profile photo.');documents[key]=await upload(file,'carmitra-documents','verification');}}await action('apply_partner',{...application,equipment:application.equipment==='true',transportation:!!application.transportation,agreement_accept:true,agreement_version:f.dataset.agreementVersion,documents});application={};documents={};portalStep=1;go('partner-portal');}
 if(f.id==='nominee-form'){await operations('nominate_partner',{full_name:data['nominee-name'],phone:data['nominee-phone'],locality:data['nominee-area'],note:data['nominee-note']});$('#portal-message').innerHTML=notice('Nomination saved for admin onboarding review.');f.reset();}
 if(f.id==='profile-form'){if(photoSavePending)await photoSavePending;const dob=validateBirthDate(String(data['profile-dob']||'').trim()),gender=data['profile-gender']||null,email=String(data['profile-email']||'').trim(),phone=String(data['profile-phone']||'').replace(/\D/g,'').replace(/^91(?=\d{10}$)/,'');if(gender&&!['male','female','other'].includes(gender))throw Error('Choose Male, Female or Others.');if(email&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email))throw Error('Enter a valid contact email.');if(!/^[6-9][0-9]{9}$/.test(phone))throw Error('Enter a valid 10-digit mobile number.');const user=await client.api('/auth/v1/user'),file=$('#profile-photo')?.files?.[0];let path=profileRecord.photo_path||null,uploaded=false;if(file){path=await upload(file,'carmitra-avatars','profile');uploaded=true;}try{await client.api('/rest/v1/carmitra_profiles?on_conflict=user_id',{method:'POST',headers:{Prefer:'resolution=merge-duplicates,return=representation'},body:{user_id:user.id,full_name:data['profile-name'].trim(),phone,date_of_birth:dob,gender,contact_email:email,photo_path:path}}).then(rows=>{if(!rows[0]||rows[0].phone!==phone)throw Error('Mobile number could not save. Please retry.');});}catch(error){if(uploaded)await client.api('/storage/v1/object/carmitra-avatars',{method:'DELETE',body:{prefixes:[path]}}).catch(()=>{});throw error;}const old=profileRecord.photo_path;profileRecord={...profileRecord,photo_path:path,phone};if(uploaded&&old&&old!==path)await client.api('/storage/v1/object/carmitra-avatars',{method:'DELETE',body:{prefixes:[old]}}).catch(()=>{});await client.refreshIdentity();if(activePortal==='profile')$('#portal-message').innerHTML=notice('Profile updated successfully.');}
 if(f.id==='channel-form'){channelDraft=data;channelModel=data.tier;if(!data['channel-budget'])throw Error('Choose your available investment budget.');if(!client.session){client.setReturnPage('channel');client.navigate('login');return;}await action('apply_channel',{full_name:data['channel-name'].trim(),phone:data['channel-phone'],email:data['channel-email'].trim(),city:'Jaipur',tier:data.tier,locality:data['channel-area'],experience:data['channel-experience'],motivation:data['channel-motivation'].trim(),investment_budget:data['channel-budget']});channelDraft={};go('channel-portal')}
 if(f.id==='payout-form'){await action('request_payout',{amount_paise:Math.round(Number(data['payout-amount'])*100),upi:data['payout-upi']});render('partner-portal',false)}
 if(f.classList.contains('job-form')){const path=await upload($('#photo-'+f.dataset.id).files[0],'carmitra-job-media',f.dataset.id);await action('job_action',{booking_id:f.dataset.id,operation:f.dataset.operation,path,otp:data['otp-'+f.dataset.id],cash_collected:!!data.cash});render('partner-portal',false)}
 if(f.id==='admin-editor'){for(const k of ['price_paise','minimum_paise','maximum_discount_paise'])if(data[k]!==undefined&&data[k]!=='')data[k]=Math.round(Number(data[k])*100);if(data.multiplier!==undefined){data.basis_points=Math.round(Number(data.multiplier)*10000);delete data.multiplier;}for(const k of ['id','category','price_paise','duration_minutes','capacity','washes','valid_days','late_cancellation_percent','percent','minimum_paise','maximum_discount_paise','max_uses','basis_points'])if(k in data)data[k]=data[k]===''?null:Number(data[k]);for(const k of ['active','published'])if(f.querySelector('[name="'+k+'"]'))data[k]=data[k]==='on';if(data.code)data.code=data.code.trim().toUpperCase();for(const k of ['starts_at','ends_at','expires_at'])if(data[k])data[k]=new Date(data[k]+':00+05:30').toISOString();const id=f.dataset.existing,table=adminTables[adminTab];if(adminTab==='settings'){data.id=true;await client.api('/rest/v1/carmitra_site_settings?id=eq.true',{method:'PATCH',body:data})}else if(id){if(adminTab!=='services')delete data.id;await client.api('/rest/v1/carmitra_'+table+'?'+(adminTab==='areas'?'locality':adminTab==='multipliers'?'vehicle_type':'id')+'=eq.'+encodeURIComponent(id),{method:'PATCH',body:data})}else await client.api('/rest/v1/carmitra_'+table,{method:'POST',body:data});await loadAdmin();await loadPublicConfig(false);}
 if(f.id==='cancel-form'){await action('cancel',{booking_id:f.dataset.id,expected_fee_paise:Number(f.dataset.fee),reason:data['cancel-reason']});$('#portal-dialog').close();go('orders')}
 if(f.id==='review-form'){await action('review',{booking_id:f.dataset.id,display_name:data['review-name'],rating:Number(data['review-rating']),body:$('#review-body').value});$('#portal-dialog').close();go('reviews')}
 if(f.id==='warranty-form'){await action('warranty',{booking_id:f.dataset.id,description:$('#warranty-issue').value});$('#portal-dialog').close();go('orders')}
 if(f.id==='signature-form'){if(!signatureInk)throw Error('Please draw your signature.');const blob=await new Promise(r=>$('#signature-canvas').toBlob(r,'image/png'));const file=new File([blob],'signature.png',{type:'image/png'}),path=await upload(file,'carmitra-job-media',f.dataset.id);await action('customer_signature',{booking_id:f.dataset.id,path});$('#portal-dialog').close();go('orders')}
 if(f.id==='reschedule-form'){if(!data['reschedule-slot'])throw Error('Select an available slot.');await client.rpc('carmitra_reschedule',{p_booking:f.dataset.id,p_slot:data['reschedule-slot']});$('#portal-dialog').close();go('orders')}
 if(f.id==='redeem-form'){if(!data['redeem-slot'])throw Error('Choose an available slot.');await action('redeem_subscription',{subscription_id:currentSub,vehicle_id:data['redeem-vehicle'],address_id:data['redeem-address'],slot_id:data['redeem-slot'],request_id:f.dataset.requestId||=crypto.randomUUID()});$('#portal-dialog').close();go('orders')}
 });});
